# AND gate, last feature = bias 1, labels in {-1, +1}
data = [((0, 0, 1), -1), ((0, 1, 1), -1), ((1, 0, 1), -1), ((1, 1, 1), 1)]
w = [0, 0, 0]
for epoch in range(1, 10):
    mistakes = 0
    for x, y in data:
        if y * sum(wi * xi for wi, xi in zip(w, x)) <= 0:
            w = [wi + y * xi for wi, xi in zip(w, x)]
            mistakes += 1
    print(epoch, mistakes, w)
    if mistakes == 0:
        break
# last line printed: 9 0 [3, 2, -4]
